import React, { useEffect, useState } from 'react';

import {
  FiPlus,
  FiEdit2,
  FiTrash2,
  FiUpload,
  FiUsers,
  FiX,
  FiImage,
  FiMail,
  FiPhone,
} from 'react-icons/fi';

import { toast } from 'react-toastify';

import api from '../../services/api';

import { useLanguage } from '../../contexts/LanguageContext';


const AdminLeadership = () => {

  // =====================================================
  // LANGUAGE
  // =====================================================

  const { t } = useLanguage();


  // =====================================================
  // STATE
  // =====================================================

  const [members, setMembers] = useState([]);

  const [loading, setLoading] = useState(true);

  const [saving, setSaving] = useState(false);

  const [showModal, setShowModal] = useState(false);

  const [editingMember, setEditingMember] = useState(null);

  const [imageFile, setImageFile] = useState(null);

  const [imagePreview, setImagePreview] = useState(null);

  const [imageRemoved, setImageRemoved] = useState(false);


  const [formData, setFormData] = useState({
    name: '',
    position: '',
    bio: '',
    email: '',
    phone: '',
    facebook_url: '',
    linkedin_url: '',
    is_active: true,
    order: 0,
  });


  // =====================================================
  // API BASE URL
  // =====================================================

  const API_BASE_URL =
    process.env.REACT_APP_API_URL ||
    'http://127.0.0.1:8000';


  // =====================================================
  // LOAD DATA
  // =====================================================

  useEffect(() => {

    fetchMembers();

  }, []);


  const fetchMembers = async () => {

    try {

      setLoading(true);


      const response = await api.get(
        '/api/leadership/'
      );


      setMembers(
        Array.isArray(response.data)
          ? response.data
          : []
      );

    } catch (error) {

      console.error(error);


      toast.error(
        error?.response?.data?.detail ||
        t('leadership.loadFailed')
      );

    } finally {

      setLoading(false);

    }

  };


  // =====================================================
  // RESET FORM
  // =====================================================

  const resetForm = () => {

    setFormData({
      name: '',
      position: '',
      bio: '',
      email: '',
      phone: '',
      facebook_url: '',
      linkedin_url: '',
      is_active: true,
      order: 0,
    });


    setEditingMember(null);

    setImageFile(null);

    setImagePreview(null);

    setImageRemoved(false);

  };


  // =====================================================
  // ADD
  // =====================================================

  const handleAdd = () => {

    resetForm();

    setShowModal(true);

  };


  // =====================================================
  // EDIT
  // =====================================================

  const handleEdit = (member) => {

    setEditingMember(member);


    setFormData({

      name:
        member.name || '',

      position:
        member.position || '',

      bio:
        member.bio || '',

      email:
        member.email || '',

      phone:
        member.phone || '',

      facebook_url:
        member.facebook_url || '',

      linkedin_url:
        member.linkedin_url || '',

      is_active:
        member.is_active ?? true,

      order:
        member.order ?? 0,

    });


    if (member.image) {

      setImagePreview(
        member.image.startsWith('http')
          ? member.image
          : `${API_BASE_URL}${member.image}`
      );

    } else {

      setImagePreview(null);

    }


    setImageFile(null);

    setImageRemoved(false);

    setShowModal(true);

  };


  // =====================================================
  // CLOSE MODAL
  // =====================================================

  const handleCloseModal = () => {

    setShowModal(false);

    resetForm();

  };


  // =====================================================
  // INPUT
  // =====================================================

  const handleChange = (e) => {

    const {
      name,
      value,
      type,
      checked,
    } = e.target;


    setFormData((prev) => ({

      ...prev,

      [name]:
        type === 'checkbox'
          ? checked
          : value,

    }));

  };


  // =====================================================
  // IMAGE CHANGE
  // =====================================================

  const handleImageChange = (e) => {

    const file =
      e.target.files?.[0];


    if (!file) {
      return;
    }


    const allowedTypes = [
      'image/jpeg',
      'image/jpg',
      'image/png',
      'image/webp',
    ];


    if (
      !allowedTypes.includes(
        file.type
      )
    ) {

      toast.error(
        t(
          'leadership.invalidImage'
        )
      );


      e.target.value = '';

      return;

    }


    if (
      file.size >
      5 * 1024 * 1024
    ) {

      toast.error(
        t(
          'leadership.imageTooLarge'
        )
      );


      e.target.value = '';

      return;

    }


    if (
      imagePreview?.startsWith(
        'blob:'
      )
    ) {

      URL.revokeObjectURL(
        imagePreview
      );

    }


    setImageFile(file);


    setImagePreview(
      URL.createObjectURL(file)
    );


    setImageRemoved(false);

  };


  // =====================================================
  // REMOVE IMAGE
  // =====================================================

  const handleRemoveImage = () => {

    if (
      imagePreview?.startsWith(
        'blob:'
      )
    ) {

      URL.revokeObjectURL(
        imagePreview
      );

    }


    setImageFile(null);

    setImagePreview(null);

    setImageRemoved(true);

  };


  // =====================================================
  // SUBMIT
  // =====================================================

  const handleSubmit = async (e) => {

    e.preventDefault();


    // ===================================================
    // VALIDATION
    // ===================================================

    if (
      !formData.name.trim()
    ) {

      toast.error(
        t(
          'leadership.nameRequired'
        )
      );

      return;

    }


    if (
      !formData.position.trim()
    ) {

      toast.error(
        t(
          'leadership.positionRequired'
        )
      );

      return;

    }


    try {

      setSaving(true);


      const data =
        new FormData();


      // =================================================
      // REQUIRED
      // =================================================

      data.append(
        'name',
        formData.name.trim()
      );


      data.append(
        'position',
        formData.position.trim()
      );


      // =================================================
      // OPTIONAL
      // =================================================

      if (formData.bio) {

        data.append(
          'bio',
          formData.bio
        );

      }


      if (formData.email) {

        data.append(
          'email',
          formData.email
        );

      }


      if (formData.phone) {

        data.append(
          'phone',
          formData.phone
        );

      }


      if (
        formData.facebook_url
      ) {

        data.append(
          'facebook_url',
          formData.facebook_url
        );

      }


      if (
        formData.linkedin_url
      ) {

        data.append(
          'linkedin_url',
          formData.linkedin_url
        );

      }


      data.append(
        'is_active',
        String(
          formData.is_active
        )
      );


      data.append(
        'order',
        String(
          formData.order || 0
        )
      );


      // =================================================
      // IMAGE
      // =================================================

      if (imageFile) {

        data.append(
          'image',
          imageFile
        );

      }


      if (
        editingMember &&
        imageRemoved &&
        !imageFile
      ) {

        data.append(
          'remove_image',
          'true'
        );

      }


      // =================================================
      // UPDATE
      // =================================================

      if (editingMember) {

        await api.put(
          `/api/leadership/${editingMember.id}`,
          data
        );


        toast.success(
          t(
            'leadership.updatedSuccess'
          )
        );

      }


      // =================================================
      // CREATE
      // =================================================

      else {

        await api.post(
          '/api/leadership/',
          data
        );


        toast.success(
          t(
            'leadership.createdSuccess'
          )
        );

      }


      handleCloseModal();


      await fetchMembers();

    } catch (error) {

      console.error(error);


      const detail =
        error?.response?.data?.detail;


      if (
        Array.isArray(detail)
      ) {

        toast.error(
          detail[0]?.msg ||
          t(
            'common.validationError'
          )
        );

      } else {

        toast.error(
          detail ||
          t(
            'leadership.saveFailed'
          )
        );

      }

    } finally {

      setSaving(false);

    }

  };


  // =====================================================
  // DELETE
  // =====================================================

  const handleDelete = async (member) => {

    const confirmed =
      window.confirm(
        `${t(
          'leadership.deleteConfirm'
        )} "${member.name}"?`
      );


    if (!confirmed) {
      return;
    }


    try {

      await api.delete(
        `/api/leadership/${member.id}`
      );


      toast.success(
        t(
          'leadership.deletedSuccess'
        )
      );


      await fetchMembers();

    } catch (error) {

      console.error(error);


      toast.error(
        error?.response?.data?.detail ||
        t(
          'leadership.deleteFailed'
        )
      );

    }

  };


  // =====================================================
  // IMAGE URL
  // =====================================================

  const getImageUrl = (image) => {

    if (!image) {
      return null;
    }


    if (
      image.startsWith('http')
    ) {

      return image;

    }


    return `${API_BASE_URL}${image}`;

  };


  // =====================================================
  // ACTIVE COUNT
  // =====================================================

  const activeCount =
    members.filter(
      (member) =>
        member.is_active
    ).length;


  // =====================================================
  // LOADING
  // =====================================================

  if (loading) {

    return (

      <div
        className="
          min-h-[400px]
          flex
          items-center
          justify-center
        "
      >

        <div className="text-center">

          <div
            className="
              w-10
              h-10
              border-4
              border-blue-200
              border-t-blue-900
              rounded-full
              animate-spin
              mx-auto
            "
          />


          <p
            className="
              text-blue-400
              text-sm
              mt-4
            "
          >
            {t(
              'leadership.loading'
            )}
          </p>

        </div>

      </div>

    );

  }


  // =====================================================
  // RENDER
  // =====================================================

  return (

    <div
      className="
        p-4
        md:p-6
        lg:p-8
        bg-white
        min-h-screen
      "
    >


      {/* =================================================
          HEADER
      ================================================== */}

      <div
        className="
          flex
          flex-col
          sm:flex-row
          sm:items-center
          sm:justify-between
          gap-4
          mb-6
        "
      >

        <div
          className="
            flex
            items-center
            gap-3
          "
        >

          <div
            className="
              w-11
              h-11
              bg-blue-900
              rounded-xl
              flex
              items-center
              justify-center
              text-white
              shadow-sm
            "
          >

            <FiUsers size={20} />

          </div>


          <div>

            <h1
              className="
                text-xl
                md:text-2xl
                font-bold
                text-blue-900
                leading-tight
              "
            >
              {t(
                'leadership.title'
              )}
            </h1>


            <p
              className="
                text-blue-400
                text-sm
                mt-1
              "
            >
              {t(
                'leadership.subtitle'
              )}
            </p>

          </div>

        </div>


        <button
          type="button"

          onClick={handleAdd}

          className="
            h-10
            px-4
            bg-red-600
            text-white
            rounded-lg
            text-sm
            font-semibold
            inline-flex
            items-center
            justify-center
            gap-2
            shadow-sm
            hover:bg-red-700
            hover:shadow-md
            transition-all
            duration-200
          "
        >

          <FiPlus size={17} />


          {t(
            'leadership.addMember'
          )}

        </button>

      </div>


      {/* =================================================
          TABLE CARD
      ================================================== */}

      <div
        className="
          bg-white
          border
          border-blue-200
          rounded-xl
          shadow-sm
          overflow-hidden
        "
      >


        {/* CARD HEADER */}

        <div
          className="
            px-5
            py-4
            border-b
            border-blue-200
            flex
            items-center
            justify-between
          "
        >

          <div>

            <h2
              className="
                font-bold
                text-blue-900
              "
            >
              {t(
                'leadership.members'
              )}
            </h2>


            <p
              className="
                text-xs
                text-blue-300
                mt-1
              "
            >

              {members.length}{' '}

              {
                members.length === 1
                  ? t(
                      'leadership.member'
                    )
                  : t(
                      'leadership.memberPlural'
                    )
              }

            </p>

          </div>


          <div
            className="
              px-3
              py-1.5
              bg-blue-50
              text-blue-900
              text-xs
              font-semibold
              rounded-full
            "
          >

            {activeCount}{' '}

            {t(
              'common.active'
            )}

          </div>

        </div>


        {/* =================================================
            EMPTY
        ================================================== */}

        {
          members.length === 0 ? (

            <div
              className="
                py-16
                px-5
                text-center
              "
            >

              <div
                className="
                  w-16
                  h-16
                  bg-blue-50
                  rounded-full
                  flex
                  items-center
                  justify-center
                  mx-auto
                  mb-4
                "
              >

                <FiUsers
                  size={27}
                  className="text-blue-900"
                />

              </div>


              <h3
                className="
                  text-lg
                  font-bold
                  text-blue-900
                "
              >
                {t(
                  'leadership.noMembers'
                )}
              </h3>


              <p
                className="
                  text-blue-400
                  text-sm
                  mt-2
                  mb-5
                "
              >
                {t(
                  'leadership.addFirstMember'
                )}
              </p>


              <button
                type="button"

                onClick={handleAdd}

                className="
                  h-10
                  px-5
                  bg-red-600
                  text-white
                  rounded-lg
                  inline-flex
                  items-center
                  gap-2
                  text-sm
                  font-semibold
                  hover:bg-red-700
                  transition
                "
              >

                <FiPlus />


                {t(
                  'leadership.addMember'
                )}

              </button>

            </div>

          ) : (


            /* =================================================
                TABLE
            ================================================== */

            <div className="overflow-x-auto">

              <table
                className="
                  w-full
                  min-w-[900px]
                "
              >

                <thead>

                  <tr
                    className="
                      bg-blue-50
                      border-b
                      border-blue-200
                    "
                  >

                    <th
                      className="
                        px-5
                        py-3.5
                        text-left
                        text-[11px]
                        font-bold
                        text-blue-400
                        uppercase
                        tracking-wider
                      "
                    >
                      #
                    </th>


                    <th
                      className="
                        px-4
                        py-3.5
                        text-left
                        text-[11px]
                        font-bold
                        text-blue-400
                        uppercase
                        tracking-wider
                      "
                    >
                      {t(
                        'leadership.member'
                      )}
                    </th>


                    <th
                      className="
                        px-4
                        py-3.5
                        text-left
                        text-[11px]
                        font-bold
                        text-blue-400
                        uppercase
                        tracking-wider
                      "
                    >
                      {t(
                        'leadership.position'
                      )}
                    </th>


                    <th
                      className="
                        px-4
                        py-3.5
                        text-left
                        text-[11px]
                        font-bold
                        text-blue-400
                        uppercase
                        tracking-wider
                      "
                    >
                      {t(
                        'leadership.contact'
                      )}
                    </th>


                    <th
                      className="
                        px-4
                        py-3.5
                        text-center
                        text-[11px]
                        font-bold
                        text-blue-400
                        uppercase
                        tracking-wider
                      "
                    >
                      {t(
                        'common.status'
                      )}
                    </th>


                    <th
                      className="
                        px-4
                        py-3.5
                        text-center
                        text-[11px]
                        font-bold
                        text-blue-400
                        uppercase
                        tracking-wider
                      "
                    >
                      {t(
                        'leadership.order'
                      )}
                    </th>


                    <th
                      className="
                        px-5
                        py-3.5
                        text-right
                        text-[11px]
                        font-bold
                        text-blue-400
                        uppercase
                        tracking-wider
                      "
                    >
                      {t(
                        'common.actions'
                      )}
                    </th>

                  </tr>

                </thead>


                <tbody
                  className="
                    divide-y
                    divide-blue-200
                  "
                >

                  {
                    members.map(
                      (
                        member,
                        index
                      ) => (

                        <tr
                          key={
                            member.id
                          }

                          className="
                            hover:bg-blue-50
                            transition-colors
                            duration-200
                          "
                        >


                          {/* NUMBER */}

                          <td
                            className="
                              px-5
                              py-4
                            "
                          >

                            <span
                              className="
                                text-sm
                                text-blue-400
                              "
                            >
                              {
                                String(
                                  index + 1
                                ).padStart(
                                  2,
                                  '0'
                                )
                              }
                            </span>

                          </td>


                          {/* MEMBER */}

                          <td
                            className="
                              px-4
                              py-4
                            "
                          >

                            <div
                              className="
                                flex
                                items-center
                                gap-3
                              "
                            >

                              {
                                member.image ? (

                                  <img
                                    src={
                                      getImageUrl(
                                        member.image
                                      )
                                    }

                                    alt={
                                      member.name
                                    }

                                    className="
                                      w-[52px]
                                      h-[52px]
                                      rounded-xl
                                      object-cover
                                      border
                                      border-blue-200
                                      shadow-sm
                                      flex-shrink-0
                                    "
                                  />

                                ) : (

                                  <div
                                    className="
                                      w-[52px]
                                      h-[52px]
                                      rounded-xl
                                      bg-blue-50
                                      flex
                                      items-center
                                      justify-center
                                      flex-shrink-0
                                    "
                                  >

                                    <FiUsers
                                      size={20}
                                      className="text-blue-900"
                                    />

                                  </div>

                                )
                              }


                              <div className="min-w-0">

                                <p
                                  className="
                                    text-sm
                                    font-bold
                                    text-blue-900
                                    truncate
                                  "
                                >
                                  {member.name}
                                </p>


                                {
                                  member.email && (

                                    <p
                                      className="
                                        text-xs
                                        text-blue-400
                                        truncate
                                        mt-1
                                        max-w-[190px]
                                      "
                                    >
                                      {
                                        member.email
                                      }
                                    </p>

                                  )
                                }

                              </div>

                            </div>

                          </td>


                          {/* POSITION */}

                          <td
                            className="
                              px-4
                              py-4
                            "
                          >

                            <span
                              className="
                                text-sm
                                text-blue-900
                                font-medium
                              "
                            >
                              {
                                member.position
                              }
                            </span>

                          </td>


                          {/* CONTACT */}

                          <td
                            className="
                              px-4
                              py-4
                            "
                          >

                            <div className="space-y-1">

                              {
                                member.phone ? (

                                  <div
                                    className="
                                      flex
                                      items-center
                                      gap-2
                                      text-xs
                                      text-blue-500
                                    "
                                  >

                                    <FiPhone
                                      size={13}
                                      className="text-red-600"
                                    />


                                    {
                                      member.phone
                                    }

                                  </div>

                                ) : (

                                  <span
                                    className="
                                      text-blue-300
                                    "
                                  >
                                    —
                                  </span>

                                )
                              }


                              {
                                member.email && (

                                  <div
                                    className="
                                      flex
                                      items-center
                                      gap-2
                                      text-xs
                                      text-blue-500
                                    "
                                  >

                                    <FiMail
                                      size={13}
                                      className="text-blue-900"
                                    />


                                    <span
                                      className="
                                        truncate
                                        max-w-[180px]
                                      "
                                    >
                                      {
                                        member.email
                                      }
                                    </span>

                                  </div>

                                )
                              }

                            </div>

                          </td>


                          {/* STATUS */}

                          <td
                            className="
                              px-4
                              py-4
                              text-center
                            "
                          >

                            <span
                              className={`
                                inline-flex
                                items-center
                                gap-1.5
                                px-2.5
                                py-1
                                rounded-full
                                text-[11px]
                                font-semibold

                                ${
                                  member.is_active
                                    ? 'bg-blue-50 text-blue-700'
                                    : 'bg-red-50 text-red-600'
                                }
                              `}
                            >

                              <span
                                className={`
                                  w-1.5
                                  h-1.5
                                  rounded-full

                                  ${
                                    member.is_active
                                      ? 'bg-blue-500'
                                      : 'bg-red-500'
                                  }
                                `}
                              />


                              {
                                member.is_active
                                  ? t(
                                      'common.active'
                                    )
                                  : t(
                                      'common.inactive'
                                    )
                              }

                            </span>

                          </td>


                          {/* ORDER */}

                          <td
                            className="
                              px-4
                              py-4
                              text-center
                            "
                          >

                            <span
                              className="
                                inline-flex
                                items-center
                                justify-center
                                min-w-[30px]
                                h-[30px]
                                px-2
                                bg-blue-50
                                rounded-lg
                                text-xs
                                font-bold
                                text-blue-900
                              "
                            >
                              {member.order}
                            </span>

                          </td>


                          {/* ACTIONS */}

                          <td
                            className="
                              px-5
                              py-4
                            "
                          >

                            <div
                              className="
                                flex
                                items-center
                                justify-end
                                gap-2
                              "
                            >

                              <button
                                type="button"

                                onClick={() =>
                                  handleEdit(
                                    member
                                  )
                                }

                                title={
                                  t(
                                    'common.edit'
                                  )
                                }

                                className="
                                  w-9
                                  h-9
                                  rounded-lg
                                  bg-blue-50
                                  text-blue-900
                                  flex
                                  items-center
                                  justify-center
                                  hover:bg-blue-900
                                  hover:text-white
                                  transition-all
                                  duration-200
                                "
                              >

                                <FiEdit2
                                  size={15}
                                />

                              </button>


                              <button
                                type="button"

                                onClick={() =>
                                  handleDelete(
                                    member
                                  )
                                }

                                title={
                                  t(
                                    'common.delete'
                                  )
                                }

                                className="
                                  w-9
                                  h-9
                                  rounded-lg
                                  bg-red-50
                                  text-red-600
                                  flex
                                  items-center
                                  justify-center
                                  hover:bg-red-600
                                  hover:text-white
                                  transition-all
                                  duration-200
                                "
                              >

                                <FiTrash2
                                  size={15}
                                />

                              </button>

                            </div>

                          </td>

                        </tr>

                      )
                    )
                  }

                </tbody>

              </table>

            </div>

          )
        }

      </div>


      {/* =================================================
          MODAL
      ================================================== */}

      {
        showModal && (

          <div
            className="
              fixed
              inset-0
              z-[9999]
              bg-blue-900/50
              backdrop-blur-[2px]
              flex
              items-center
              justify-center
              p-4
            "

            onMouseDown={(e) => {

              if (
                e.target ===
                e.currentTarget
              ) {

                handleCloseModal();

              }

            }}
          >

            <div
              className="
                bg-white
                w-full
                max-w-[760px]
                max-h-[92vh]
                rounded-2xl
                shadow-2xl
                overflow-hidden
                flex
                flex-col
              "
            >


              {/* =========================================
                  MODAL HEADER
              ========================================== */}

              <div
                className="
                  px-5
                  md:px-6
                  py-4
                  bg-blue-900
                  flex
                  items-center
                  justify-between
                  flex-shrink-0
                "
              >

                <div
                  className="
                    flex
                    items-center
                    gap-3
                  "
                >

                  <div
                    className="
                      w-10
                      h-10
                      bg-red-600
                      rounded-lg
                      flex
                      items-center
                      justify-center
                      text-white
                    "
                  >

                    {
                      editingMember ? (

                        <FiEdit2
                          size={17}
                        />

                      ) : (

                        <FiPlus
                          size={18}
                        />

                      )
                    }

                  </div>


                  <div>

                    <p
                      className="
                        text-white/40
                        text-[10px]
                        uppercase
                        font-bold
                        tracking-widest
                      "
                    >
                      {t(
                        'leadership.management'
                      )}
                    </p>


                    <h2
                      className="
                        text-white
                        text-lg
                        font-bold
                        mt-0.5
                      "
                    >

                      {
                        editingMember
                          ? t(
                              'leadership.editMember'
                            )
                          : t(
                              'leadership.addLeadershipMember'
                            )
                      }

                    </h2>

                  </div>

                </div>


                <button
                  type="button"

                  onClick={
                    handleCloseModal
                  }

                  disabled={
                    saving
                  }

                  className="
                    w-9
                    h-9
                    bg-white/10
                    rounded-lg
                    text-white
                    flex
                    items-center
                    justify-center
                    hover:bg-red-600
                    transition
                  "
                >

                  <FiX size={19} />

                </button>

              </div>


              {/* =========================================
                  FORM
              ========================================== */}

              <form
                onSubmit={
                  handleSubmit
                }

                className="
                  flex
                  flex-col
                  min-h-0
                "
              >


                {/* BODY */}

                <div
                  className="
                    p-5
                    md:p-6
                    overflow-y-auto
                  "
                >


                  {/* =====================================
                      PHOTO
                  ====================================== */}

                  <div
                    className="
                      bg-blue-50
                      border
                      border-blue-200
                      rounded-xl
                      p-4
                      mb-6
                    "
                  >

                    <label
                      className="
                        block
                        text-sm
                        font-bold
                        text-blue-900
                        mb-3
                      "
                    >
                      {t(
                        'leadership.memberPhoto'
                      )}
                    </label>


                    <div
                      className="
                        flex
                        flex-col
                        sm:flex-row
                        sm:items-center
                        gap-4
                      "
                    >


                      {/* PREVIEW */}

                      <div
                        className="
                          w-[100px]
                          h-[100px]
                          rounded-xl
                          overflow-hidden
                          bg-white
                          border
                          border-blue-200
                          flex
                          items-center
                          justify-center
                          flex-shrink-0
                        "
                      >

                        {
                          imagePreview ? (

                            <img
                              src={
                                imagePreview
                              }

                              alt={
                                t(
                                  'leadership.preview'
                                )
                              }

                              className="
                                w-full
                                h-full
                                object-cover
                              "
                            />

                          ) : (

                            <FiImage
                              size={30}
                              className="text-blue-300"
                            />

                          )
                        }

                      </div>


                      <div>

                        <div
                          className="
                            flex
                            flex-wrap
                            gap-2
                          "
                        >

                          <label
                            className="
                              h-10
                              px-4
                              bg-blue-900
                              text-white
                              rounded-lg
                              text-sm
                              font-semibold
                              inline-flex
                              items-center
                              justify-center
                              gap-2
                              cursor-pointer
                              hover:bg-blue-700
                              transition
                            "
                          >

                            <FiUpload
                              size={16}
                            />


                            {t(
                              'leadership.chooseImage'
                            )}


                            <input
                              type="file"

                              accept="
                                image/png,
                                image/jpeg,
                                image/webp
                              "

                              hidden

                              onChange={
                                handleImageChange
                              }
                            />

                          </label>


                          {
                            imagePreview && (

                              <button
                                type="button"

                                onClick={
                                  handleRemoveImage
                                }

                                className="
                                  h-10
                                  px-4
                                  bg-red-50
                                  text-red-600
                                  rounded-lg
                                  text-sm
                                  font-semibold
                                  hover:bg-red-600
                                  hover:text-white
                                  transition
                                "
                              >
                                {t(
                                  'common.remove'
                                )}
                              </button>

                            )
                          }

                        </div>


                        <p
                          className="
                            text-xs
                            text-blue-300
                            mt-2
                          "
                        >
                          {t(
                            'leadership.imageHelp'
                          )}
                        </p>

                      </div>

                    </div>

                  </div>


                  {/* =====================================
                      FORM GRID
                  ====================================== */}

                  <div
                    className="
                      grid
                      md:grid-cols-2
                      gap-5
                    "
                  >


                    {/* NAME */}

                    <div>

                      <label
                        className="
                          block
                          text-sm
                          font-semibold
                          text-blue-900
                          mb-2
                        "
                      >

                        {t(
                          'leadership.name'
                        )}


                        <span
                          className="
                            text-red-600
                            ml-1
                          "
                        >
                          *
                        </span>

                      </label>


                      <input
                        type="text"

                        name="name"

                        value={
                          formData.name
                        }

                        onChange={
                          handleChange
                        }

                        placeholder={
                          t(
                            'leadership.namePlaceholder'
                          )
                        }

                        required

                        className="
                          w-full
                          h-11
                          px-4
                          border
                          border-blue-200
                          rounded-lg
                          text-sm
                          text-blue-900
                          outline-none
                          focus:border-blue-900
                          focus:ring-2
                          focus:ring-blue-900/10
                          transition
                        "
                      />

                    </div>


                    {/* POSITION */}

                    <div>

                      <label
                        className="
                          block
                          text-sm
                          font-semibold
                          text-blue-900
                          mb-2
                        "
                      >

                        {t(
                          'leadership.position'
                        )}


                        <span
                          className="
                            text-red-600
                            ml-1
                          "
                        >
                          *
                        </span>

                      </label>


                      <input
                        type="text"

                        name="position"

                        value={
                          formData.position
                        }

                        onChange={
                          handleChange
                        }

                        placeholder={
                          t(
                            'leadership.positionPlaceholder'
                          )
                        }

                        required

                        className="
                          w-full
                          h-11
                          px-4
                          border
                          border-blue-200
                          rounded-lg
                          text-sm
                          text-blue-900
                          outline-none
                          focus:border-blue-900
                          focus:ring-2
                          focus:ring-blue-900/10
                          transition
                        "
                      />

                    </div>


                    {/* EMAIL */}

                    <div>

                      <label
                        className="
                          block
                          text-sm
                          font-semibold
                          text-blue-900
                          mb-2
                        "
                      >
                        {t(
                          'leadership.email'
                        )}
                      </label>


                      <input
                        type="email"

                        name="email"

                        value={
                          formData.email
                        }

                        onChange={
                          handleChange
                        }

                        placeholder="example@email.com"

                        className="
                          w-full
                          h-11
                          px-4
                          border
                          border-blue-200
                          rounded-lg
                          text-sm
                          text-blue-900
                          outline-none
                          focus:border-blue-900
                          focus:ring-2
                          focus:ring-blue-900/10
                          transition
                        "
                      />

                    </div>


                    {/* PHONE */}

                    <div>

                      <label
                        className="
                          block
                          text-sm
                          font-semibold
                          text-blue-900
                          mb-2
                        "
                      >
                        {t(
                          'leadership.phone'
                        )}
                      </label>


                      <input
                        type="text"

                        name="phone"

                        value={
                          formData.phone
                        }

                        onChange={
                          handleChange
                        }

                        placeholder="012 345 678"

                        className="
                          w-full
                          h-11
                          px-4
                          border
                          border-blue-200
                          rounded-lg
                          text-sm
                          text-blue-900
                          outline-none
                          focus:border-blue-900
                          focus:ring-2
                          focus:ring-blue-900/10
                          transition
                        "
                      />

                    </div>


                    {/* FACEBOOK */}

                    <div>

                      <label
                        className="
                          block
                          text-sm
                          font-semibold
                          text-blue-900
                          mb-2
                        "
                      >
                        Facebook
                      </label>


                      <input
                        type="text"

                        name="facebook_url"

                        value={
                          formData.facebook_url
                        }

                        onChange={
                          handleChange
                        }

                        placeholder={
                          t(
                            'leadership.facebookPlaceholder'
                          )
                        }

                        className="
                          w-full
                          h-11
                          px-4
                          border
                          border-blue-200
                          rounded-lg
                          text-sm
                          text-blue-900
                          outline-none
                          focus:border-blue-900
                          focus:ring-2
                          focus:ring-blue-900/10
                          transition
                        "
                      />

                    </div>


                    {/* LINKEDIN */}

                    <div>

                      <label
                        className="
                          block
                          text-sm
                          font-semibold
                          text-blue-900
                          mb-2
                        "
                      >
                        LinkedIn
                      </label>


                      <input
                        type="text"

                        name="linkedin_url"

                        value={
                          formData.linkedin_url
                        }

                        onChange={
                          handleChange
                        }

                        placeholder={
                          t(
                            'leadership.linkedinPlaceholder'
                          )
                        }

                        className="
                          w-full
                          h-11
                          px-4
                          border
                          border-blue-200
                          rounded-lg
                          text-sm
                          text-blue-900
                          outline-none
                          focus:border-blue-900
                          focus:ring-2
                          focus:ring-blue-900/10
                          transition
                        "
                      />

                    </div>


                    {/* ORDER */}

                    <div>

                      <label
                        className="
                          block
                          text-sm
                          font-semibold
                          text-blue-900
                          mb-2
                        "
                      >
                        {t(
                          'leadership.displayOrder'
                        )}
                      </label>


                      <input
                        type="number"

                        name="order"

                        min="0"

                        value={
                          formData.order
                        }

                        onChange={
                          handleChange
                        }

                        className="
                          w-full
                          h-11
                          px-4
                          border
                          border-blue-200
                          rounded-lg
                          text-sm
                          text-blue-900
                          outline-none
                          focus:border-blue-900
                          focus:ring-2
                          focus:ring-blue-900/10
                          transition
                        "
                      />

                    </div>


                    {/* STATUS */}

                    <div>

                      <label
                        className="
                          block
                          text-sm
                          font-semibold
                          text-blue-900
                          mb-2
                        "
                      >
                        {t(
                          'common.status'
                        )}
                      </label>


                      <div
                        className="
                          h-11
                          px-4
                          border
                          border-blue-200
                          rounded-lg
                          flex
                          items-center
                          justify-between
                        "
                      >

                        <span
                          className={`
                            text-sm
                            font-semibold

                            ${
                              formData.is_active
                                ? 'text-blue-600'
                                : 'text-blue-400'
                            }
                          `}
                        >

                          {
                            formData.is_active
                              ? t(
                                  'common.active'
                                )
                              : t(
                                  'common.inactive'
                                )
                          }

                        </span>


                        <label
                          className="
                            relative
                            inline-flex
                            items-center
                            cursor-pointer
                          "
                        >

                          <input
                            type="checkbox"

                            name="is_active"

                            checked={
                              formData.is_active
                            }

                            onChange={
                              handleChange
                            }

                            className="
                              sr-only
                              peer
                            "
                          />


                          <div
                            className="
                              w-10
                              h-5
                              bg-blue-200
                              rounded-full
                              peer
                              peer-checked:bg-blue-600

                              after:content-['']
                              after:absolute
                              after:top-[2px]
                              after:left-[2px]
                              after:w-4
                              after:h-4
                              after:bg-white
                              after:rounded-full
                              after:transition-all

                              peer-checked:after:translate-x-5
                            "
                          />

                        </label>

                      </div>

                    </div>


                    {/* BIO */}

                    <div
                      className="
                        md:col-span-2
                      "
                    >

                      <label
                        className="
                          block
                          text-sm
                          font-semibold
                          text-blue-900
                          mb-2
                        "
                      >
                        {t(
                          'leadership.biography'
                        )}
                      </label>


                      <textarea
                        name="bio"

                        rows="4"

                        value={
                          formData.bio
                        }

                        onChange={
                          handleChange
                        }

                        placeholder={
                          t(
                            'leadership.bioPlaceholder'
                          )
                        }

                        className="
                          w-full
                          px-4
                          py-3
                          border
                          border-blue-200
                          rounded-lg
                          text-sm
                          text-blue-900
                          outline-none
                          resize-none
                          focus:border-blue-900
                          focus:ring-2
                          focus:ring-blue-900/10
                          transition
                        "
                      />

                    </div>

                  </div>

                </div>


                {/* =========================================
                    FOOTER
                ========================================== */}

                <div
                  className="
                    px-5
                    md:px-6
                    py-4
                    bg-blue-50
                    border-t
                    border-blue-200
                    flex
                    items-center
                    justify-end
                    gap-3
                    flex-shrink-0
                  "
                >

                  <button
                    type="button"

                    onClick={
                      handleCloseModal
                    }

                    disabled={
                      saving
                    }

                    className="
                      h-10
                      px-5
                      bg-white
                      border
                      border-blue-200
                      text-blue-400
                      rounded-lg
                      text-sm
                      font-semibold
                      hover:bg-blue-50
                      disabled:opacity-50
                      disabled:cursor-not-allowed
                      transition
                    "
                  >
                    {t(
                      'common.cancel'
                    )}
                  </button>


                  <button
                    type="submit"

                    disabled={
                      saving
                    }

                    className="
                      min-w-[130px]
                      h-10
                      px-5
                      bg-red-600
                      text-white
                      rounded-lg
                      text-sm
                      font-semibold
                      inline-flex
                      items-center
                      justify-center
                      hover:bg-red-700
                      disabled:opacity-60
                      disabled:cursor-not-allowed
                      transition
                    "
                  >

                    {
                      saving ? (

                        <>

                          <span
                            className="
                              w-4
                              h-4
                              border-2
                              border-white/30
                              border-t-white
                              rounded-full
                              animate-spin
                              mr-2
                            "
                          />


                          {t(
                            'common.saving'
                          )}

                        </>

                      ) : editingMember ? (

                        t(
                          'leadership.updateMember'
                        )

                      ) : (

                        t(
                          'leadership.addMember'
                        )

                      )
                    }

                  </button>

                </div>

              </form>

            </div>

          </div>

        )
      }

    </div>

  );

};


export default AdminLeadership;
